import * as React from "react";

export type CactusRoundIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function CactusRoundIcon({ size = 20, ...props }: CactusRoundIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="11" r="5.5"/><path d="M12 16.5V21M9 21h6"/>
    </svg>
  );
}
